+            if (next.nodeName().equalsIgnoreCase(elName)) {
                 return next;
             }
         }
@@ -334,7 +334,7 @@ public class HtmlTreeBuilder extends TreeBuilder {
         for (int pos = stack.size() -1; pos >= 0; pos--) {
             Element next = stack.get(pos);
             stack.remove(pos);
