-            if (StringUtil.in(next.nodeName(), nodeNames) || next.nodeName().equals("html"))
+            if (StringUtil.in(next.nodeName(), nodeNames) || next.nodeName().equalsIgnoreCase("html"))
                 break;
             else
                 stack.remove(pos);
@@ -566,7 +566,7 @@ public class HtmlTreeBuilder extends TreeBuilder {
      process, then the UA must perform the above steps as if that element was not in the above list.
